"use client";

import * as React from "react";
import { Select as SelectPrimitive } from "@base-ui/react/select";
import { cn } from "@/lib/utils";
import { ArrowDown01Icon, ArrowUp01Icon, Tick02Icon } from "@hugeicons/core-free-icons";
import { HaloIcon } from "@/components/icons/halo-icon";

/**
 * Select — Forms & Fields Primitive
 *
 * An accessible custom option picker for selecting one value
 * from a structured list of choices, rendered with HaloUI's
 * 10-layer physical optical liquid glass engine.
 */
const Select = SelectPrimitive.Root;

function SelectGroup({ className, ...props }: SelectPrimitive.Group.Props) {
  return (
    <SelectPrimitive.Group
      data-slot="select-group"
      className={cn("scroll-my-1 p-1", className)}
      {...props}
    />
  );
}

function SelectValue({ className, ...props }: SelectPrimitive.Value.Props) {
  return (
    <SelectPrimitive.Value
      data-slot="select-value"
      className={cn("flex flex-1 text-left truncate data-placeholder:text-muted-foreground", className)}
      {...props}
    />
  );
}

export interface SelectTriggerProps extends SelectPrimitive.Trigger.Props {
  size?: "default" | "sm";
}

function SelectTrigger({
  className,
  size = "default",
  children,
  ...props
}: SelectTriggerProps) {
  return (
    <SelectPrimitive.Trigger
      data-slot="select-trigger"
      data-size={size}
      className={cn(
        // HaloUI Physical Liquid Glass Engine (Inherited directly from Button specification)
        "halo-liquid-glass group/trigger relative flex w-full min-w-0 items-center justify-between gap-2 text-sm outline-none cursor-pointer text-foreground select-none",
        size === "sm" ? "h-8 text-xs px-2.5 rounded-lg" : "h-10 text-sm px-3.5 rounded-xl",
        // Independent Double-Contrast Focus Ring (Halo Focus Ring)
        "focus-visible:border-[var(--halo-focus-color)] focus-visible:ring-2 focus-visible:ring-[var(--halo-focus-color)] focus-visible:ring-offset-2 focus-visible:ring-offset-background halo-focus-ring",
        // Invalid state (Dual Indicator Visibility)
        "aria-invalid:border-destructive/80 aria-invalid:shadow-[inset_0_0_0_1px_rgba(244,63,94,0.3)] dark:aria-invalid:border-destructive/70",
        // Disabled state
        "disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-40 disabled:shadow-none",
        className
      )}
      {...props}
    >
      <span className="relative z-10 flex flex-1 items-center gap-2 truncate">{children}</span>
      <SelectPrimitive.Icon
        render={
          <span className="pointer-events-none relative z-10 flex size-4 items-center justify-center text-muted-foreground select-none transition-transform duration-200 group-data-[open]/trigger:rotate-180 group-data-[popup-open]/trigger:rotate-180">
            <HaloIcon icon={ArrowDown01Icon} size={15} />
          </span>
        }
      />
    </SelectPrimitive.Trigger>
  );
}

function SelectContent({
  className,
  children,
  side = "bottom",
  sideOffset = 6,
  align = "start",
  alignOffset = 0,
  alignItemWithTrigger = false,
  ...props
}: SelectPrimitive.Popup.Props &
  Pick<
    SelectPrimitive.Positioner.Props,
    "align" | "alignOffset" | "side" | "sideOffset" | "alignItemWithTrigger"
  >) {
  return (
    <SelectPrimitive.Portal>
      <SelectPrimitive.Positioner
        side={side}
        sideOffset={sideOffset}
        align={align}
        alignOffset={alignOffset}
        alignItemWithTrigger={alignItemWithTrigger}
        className="isolate z-50"
      >
        <SelectPrimitive.Popup
          data-slot="select-content"
          data-align-trigger={alignItemWithTrigger}
          className={cn(
            // HaloUI Physical Liquid Glass Floating Surface (10-layer optical engine without button hover/active physics)
            "relative isolate z-50 max-h-(--available-height) min-w-(--anchor-width) w-auto max-w-sm origin-(--transform-origin) overflow-hidden rounded-2xl p-1.5 text-foreground outline-none",
            "bg-white/90 dark:bg-neutral-950/85 backdrop-blur-2xl backdrop-saturate-200",
            "border border-border/80 dark:border-white/10 shadow-[var(--halo-shadow-elevated)]",
            // Inner optical rim & 135° specular light highlight
            "before:content-[''] before:absolute before:inset-0 before:pointer-events-none before:rounded-[inherit] before:shadow-[inset_0_1px_1px_0_rgba(255,255,255,0.85),inset_0_-1px_1px_0_rgba(0,0,0,0.04)] dark:before:shadow-[inset_0_1px_1px_0_rgba(255,255,255,0.18),inset_0_-1px_1px_0_rgba(0,0,0,0.6)]",
            "after:content-[''] after:absolute after:inset-0 after:pointer-events-none after:rounded-[inherit] after:bg-gradient-to-br after:from-white/20 after:via-white/5 after:to-transparent dark:after:from-white/10 dark:after:via-transparent dark:after:to-transparent",
            // Smooth Base UI Native CSS Transitions (Zero keyframe conflicts, zero snap-back)
            "transition-[opacity,transform] duration-150 ease-out",
            "data-[starting-style]:opacity-0 data-[starting-style]:scale-95 data-[starting-style]:data-[side=bottom]:-translate-y-1 data-[starting-style]:data-[side=top]:translate-y-1",
            "data-[ending-style]:opacity-0 data-[ending-style]:scale-95 data-[ending-style]:data-[side=bottom]:-translate-y-1 data-[ending-style]:data-[side=top]:translate-y-1",
            "data-[closed]:opacity-0 data-[closed]:scale-95 data-[closed]:pointer-events-none",
            className
          )}
          {...props}
        >
          <SelectScrollUpButton />
          <SelectPrimitive.List className="relative z-10 p-0.5 space-y-0.5">{children}</SelectPrimitive.List>
          <SelectScrollDownButton />
        </SelectPrimitive.Popup>
      </SelectPrimitive.Positioner>
    </SelectPrimitive.Portal>
  );
}

function SelectLabel({
  className,
  ...props
}: SelectPrimitive.GroupLabel.Props) {
  return (
    <SelectPrimitive.GroupLabel
      data-slot="select-label"
      className={cn("px-2.5 py-1.5 text-xs font-semibold uppercase tracking-wider text-muted-foreground select-none", className)}
      {...props}
    />
  );
}

function SelectItem({
  className,
  children,
  ...props
}: SelectPrimitive.Item.Props) {
  return (
    <SelectPrimitive.Item
      data-slot="select-item"
      className={cn(
        "relative flex w-full cursor-pointer items-center justify-between gap-2 rounded-xl py-2 pl-3 pr-8 text-sm outline-none select-none transition-all duration-150",
        // Active roving focus state: frosted glass highlight
        "data-highlighted:bg-white/80 dark:data-highlighted:bg-white/[0.14] data-highlighted:backdrop-blur-md",
        "data-highlighted:shadow-[inset_0_1px_1px_0_rgba(255,255,255,0.95),0_1px_3px_0_rgba(0,0,0,0.06)]",
        "dark:data-highlighted:shadow-[inset_0_1px_1px_0_rgba(255,255,255,0.22),0_2px_6px_0_rgba(0,0,0,0.4)]",
        "data-highlighted:text-foreground",
        // Selected committed state
        "data-selected:font-medium data-selected:text-foreground",
        // Disabled item
        "data-disabled:pointer-events-none data-disabled:cursor-not-allowed data-disabled:opacity-35",
        className
      )}
      {...props}
    >
      <SelectPrimitive.ItemText className="flex flex-1 items-center gap-2 truncate">
        {children}
      </SelectPrimitive.ItemText>
      <SelectPrimitive.ItemIndicator
        render={
          <span className="pointer-events-none absolute right-2.5 flex size-4 items-center justify-center text-primary">
            <HaloIcon icon={Tick02Icon} size={15} />
          </span>
        }
      />
    </SelectPrimitive.Item>
  );
}

function SelectSeparator({
  className,
  ...props
}: SelectPrimitive.Separator.Props) {
  return (
    <SelectPrimitive.Separator
      data-slot="select-separator"
      className={cn("pointer-events-none -mx-1 my-1 h-px bg-black/[0.08] dark:bg-white/[0.08]", className)}
      {...props}
    />
  );
}

function SelectScrollUpButton({
  className,
  ...props
}: React.ComponentProps<typeof SelectPrimitive.ScrollUpArrow>) {
  return (
    <SelectPrimitive.ScrollUpArrow
      data-slot="select-scroll-up-button"
      className={cn(
        "top-0 z-20 flex w-full cursor-default items-center justify-center bg-white/40 dark:bg-black/40 py-1 text-muted-foreground select-none backdrop-blur-md",
        className
      )}
      {...props}
    >
      <HaloIcon icon={ArrowUp01Icon} size={14} />
    </SelectPrimitive.ScrollUpArrow>
  );
}

function SelectScrollDownButton({
  className,
  ...props
}: React.ComponentProps<typeof SelectPrimitive.ScrollDownArrow>) {
  return (
    <SelectPrimitive.ScrollDownArrow
      data-slot="select-scroll-down-button"
      className={cn(
        "bottom-0 z-20 flex w-full cursor-default items-center justify-center bg-white/40 dark:bg-black/40 py-1 text-muted-foreground select-none backdrop-blur-md",
        className
      )}
      {...props}
    >
      <HaloIcon icon={ArrowDown01Icon} size={14} />
    </SelectPrimitive.ScrollDownArrow>
  );
}

export {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectScrollDownButton,
  SelectScrollUpButton,
  SelectSeparator,
  SelectTrigger,
  SelectValue,
};

export default Select;

"use client";

import * as React from "react";
import { HugeiconsIcon } from "@hugeicons/react";
import type { IconSvgElement } from "@hugeicons/react";
import { cn } from "@/lib/utils";

export type IconSize = "xs" | "sm" | "md" | "lg" | "xl" | number;

const sizeMap: Record<string, number> = {
  xs: 14,
  sm: 16,
  md: 18,
  lg: 20,
  xl: 24,
};

export interface HaloIconProps extends Omit<React.SVGProps<SVGSVGElement>, "color" | "strokeWidth" | "size"> {
  icon: IconSvgElement;
  size?: IconSize;
  strokeWidth?: number;
  className?: string;
  color?: string;
}

/**
 * Standardized HaloUI Icon wrapper using Hugeicons.
 * Guarantees currentColor inheritance, consistent optical stroke width, and crisp rendering.
 */
export function HaloIcon({
  icon,
  size = "md",
  strokeWidth = 1.5,
  className,
  color = "currentColor",
  ...props
}: HaloIconProps) {
  const pixelSize = typeof size === "number" ? size : sizeMap[size] ?? 18;

  return (
    <span
      className={cn(
        "inline-flex items-center justify-center shrink-0 select-none text-current transition-colors",
        className
      )}
      style={{ width: pixelSize, height: pixelSize }}
      aria-hidden="true"
    >
      <HugeiconsIcon
        icon={icon}
        size={pixelSize}
        strokeWidth={strokeWidth}
        color={color}
        {...props}
      />
    </span>
  );
}

/**
 * HaloUI Liquid Material Design System Tokens
 * Physical optical material engine: refraction, specular highlight, optical edges,
 * neoskeuomorphic depth, tactile compression, and virtual directional lighting.
 */

:root {
  /* Surface Tints (Light Mode: Luminous warm translucent body) */
  --halo-surface: rgba(255, 255, 255, 0.72);
  --halo-surface-elevated: rgba(255, 255, 255, 0.88);
  --halo-surface-strong: rgba(255, 255, 255, 0.95);
  --halo-surface-recessed: rgba(0, 0, 0, 0.03);
  --halo-surface-tint: rgba(245, 245, 247, 0.45);

  /* Optical Edges (Light Mode: Fine micro-reflections) */
  --halo-edge: rgba(255, 255, 255, 0.9);
  --halo-edge-soft: rgba(0, 0, 0, 0.08);
  --halo-edge-bright: rgba(255, 255, 255, 1);
  --halo-edge-inner: inset 0 1px 1px 0 rgba(255, 255, 255, 0.9), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.04);
  --halo-edge-outer: 0 0 0 1px rgba(0, 0, 0, 0.06);

  /* Specular Highlights (Directional: Virtual light at 135deg / top-left) */
  --halo-highlight: linear-gradient(135deg, rgba(255, 255, 255, 0.8) 0%, rgba(255, 255, 255, 0.15) 35%, rgba(255, 255, 255, 0) 100%);
  --halo-highlight-strength: 0.85;

  /* Optical Blur (Backdrop Diffusion) */
  --halo-blur-sm: 8px;
  --halo-blur-md: 16px;
  --halo-blur-lg: 28px;
  --halo-blur-xl: 44px;

  /* Shadows (Contact & Ambient anchoring) */
  --halo-shadow-contact: 0 1px 2px -0.5px rgba(0, 0, 0, 0.08), 0 2px 4px 0 rgba(0, 0, 0, 0.04);
  --halo-shadow-elevated: 0 6px 16px -4px rgba(0, 0, 0, 0.08), 0 2px 6px -1px rgba(0, 0, 0, 0.04);
  --halo-shadow-ambient: 0 16px 36px -8px rgba(0, 0, 0, 0.1);
  --halo-shadow-compressed: 0 1px 1px 0 rgba(0, 0, 0, 0.1);

  /* Refraction Parameters */
  --halo-refraction-strength: 0.12;
  --halo-refraction-offset: 1.5px;
  --halo-noise-opacity: 0.025;
  --halo-glow: rgba(0, 0, 0, 0.04);

  /* Corner Radii */
  --halo-radius-sm: 8px;
  --halo-radius-md: 12px;
  --halo-radius-lg: 18px;
  --halo-radius-xl: 26px;
  --halo-radius-full: 9999px;

  /* Focus Ring Tokens (Shared Accessibility Infrastructure) */
  --halo-focus-color: #0284c7;
  --halo-focus-offset: 2px;
  --halo-focus-width: 2px;
  --halo-focus-offset-color: #ffffff;
  --halo-focus-outer-color: rgba(2, 132, 199, 0.25);
  --halo-focus-shadow: 0 0 0 var(--halo-focus-offset) var(--halo-focus-offset-color), 0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width)) var(--halo-focus-color), 0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width) + 1.5px) var(--halo-focus-outer-color);

  /* Motion Presets & Timing Architecture */
  --halo-duration-micro: 120ms;
  --halo-duration-state: 180ms;
  --halo-duration-reveal: 240ms;
  --halo-duration-settle: 320ms;
  --halo-ease-tactile: cubic-bezier(0.2, 0.8, 0.3, 1);
  --halo-ease-spring: cubic-bezier(0.16, 1, 0.3, 1);
  --halo-ease-out: cubic-bezier(0, 0, 0.2, 1);

  /* Typography & Canvas (Editorial warm tone) */
  --halo-canvas: #fbfbfd;
  --halo-canvas-card: #f5f5f7;
  --halo-canvas-subtle: #eaecee;
  --halo-text-primary: #121316;
  --halo-text-secondary: #585c65;
  --halo-text-tertiary: #8b909c;
}

.dark {
  /* Surface Tints (Dark Mode: Deep graphite optical body) */
  --halo-surface: rgba(22, 23, 26, 0.7);
  --halo-surface-elevated: rgba(30, 32, 38, 0.85);
  --halo-surface-strong: rgba(38, 41, 48, 0.95);
  --halo-surface-recessed: rgba(0, 0, 0, 0.45);
  --halo-surface-tint: rgba(18, 19, 22, 0.6);

  /* Optical Edges (Dark Mode: Luminous rim catch & dark contact) */
  --halo-edge: rgba(255, 255, 255, 0.14);
  --halo-edge-soft: rgba(255, 255, 255, 0.06);
  --halo-edge-bright: rgba(255, 255, 255, 0.28);
  --halo-edge-inner: inset 0 1px 1px 0 rgba(255, 255, 255, 0.2), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.6);
  --halo-edge-outer: 0 0 0 1px rgba(255, 255, 255, 0.08);

  /* Specular Highlights (Directional top-left luminescence) */
  --halo-highlight: linear-gradient(135deg, rgba(255, 255, 255, 0.22) 0%, rgba(255, 255, 255, 0.04) 38%, rgba(255, 255, 255, 0) 100%);
  --halo-highlight-strength: 0.55;

  /* Shadows (Deep graphite depth) */
  --halo-shadow-contact: 0 1px 2px -0.5px rgba(0, 0, 0, 0.4), 0 3px 6px 0 rgba(0, 0, 0, 0.3);
  --halo-shadow-elevated: 0 8px 24px -4px rgba(0, 0, 0, 0.65), 0 3px 8px -2px rgba(0, 0, 0, 0.4);
  --halo-shadow-ambient: 0 20px 48px -12px rgba(0, 0, 0, 0.85);
  --halo-shadow-compressed: 0 1px 2px 0 rgba(0, 0, 0, 0.6);

  --halo-refraction-strength: 0.18;
  --halo-noise-opacity: 0.035;
  --halo-glow: rgba(255, 255, 255, 0.04);

  /* Focus Ring Tokens (Shared Accessibility Infrastructure) */
  --halo-focus-color: #38bdf8;
  --halo-focus-offset: 2px;
  --halo-focus-width: 2px;
  --halo-focus-offset-color: #0c0d0f;
  --halo-focus-outer-color: rgba(56, 189, 248, 0.35);
  --halo-focus-shadow: 0 0 0 var(--halo-focus-offset) var(--halo-focus-offset-color), 0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width)) var(--halo-focus-color), 0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width) + 1.5px) var(--halo-focus-outer-color);

  /* Typography & Canvas */
  --halo-canvas: #0c0d0f;
  --halo-canvas-card: #141518;
  --halo-canvas-subtle: #1c1e22;
  --halo-text-primary: #f6f7f9;
  --halo-text-secondary: #9ea3ae;
  --halo-text-tertiary: #656a76;
}

/* Explicit Stage Scopes for Interactive Previews */
.light,
[data-stage-theme="light"] {
  --halo-surface: rgba(255, 255, 255, 0.72);
  --halo-surface-elevated: rgba(255, 255, 255, 0.88);
  --halo-surface-strong: rgba(255, 255, 255, 0.95);
  --halo-surface-recessed: rgba(0, 0, 0, 0.03);
  --halo-surface-tint: rgba(245, 245, 247, 0.45);

  --halo-edge: rgba(255, 255, 255, 0.9);
  --halo-edge-soft: rgba(0, 0, 0, 0.08);
  --halo-edge-bright: rgba(255, 255, 255, 1);
